''' IMPORTS '''
import requests
import os
import csv

# disable insecure warnings
requests.packages.urllib3.disable_warnings()

''' GLOBALS '''
VERBOSE = True
SERVER = demisto.params().get('server')
if not SERVER.endswith('/'):
    SERVER += '/'
API_KEY = demisto.params().get('apikey')
MAX_AGE = demisto.params().get('days')
THRESHOLD = demisto.params().get('threshold')
INSECURE = demisto.params().get('insecure')
TEST_IP = "127.0.0.2"
BLACKLIST_SCORE = 3
CHECK_CMD = "check"
CHECK_BLOCK_CMD = "check-block"
REPORT_CMD = "report"
BLACKLIST_CMD = 'blacklist'
ANALYSIS_TITLE = "AbuseIPDB Analysis"
BLACKLIST_TITLE = "AbuseIPDB Blacklist"
REPORT_SUCCESS = "IP address reported successfully."

HEADERS = {
    'Key': API_KEY,
    'Accept': 'application/json'
}

PROXY = demisto.params().get('proxy')
if not demisto.params().get('proxy', False):
    del os.environ['HTTP_PROXY']
    del os.environ['HTTPS_PROXY']
    del os.environ['http_proxy']
    del os.environ['https_proxy']

CATEGORIES_NAME = {
    3: 'Frad_Orders',
    4: 'DDoS_Attack',
    5: 'FTP_Brute-Force',
    6: 'Ping of Death',
    7: 'Phishing',
    8: 'Fraud VoIP',
    9: 'Open_Proxy',
    10: 'Web_Spam',
    11: 'Email_Spam',
    12: 'Blog_Spam',
    13: 'VPN IP',
    14: 'Port_Scan',
    15: 'Hacking',
    16: 'SQL Injection',
    17: 'Spoofing',
    18: 'Brute_Force',
    19: 'Bad_Web_Bot',
    20: 'Exploited_Host',
    21: 'Web_App_Attack',
    22: 'SSH',
    23: 'IoT_Targeted'
}

CATEGORIES_ID = {
    "Frad_Orders": "3",
    "DDoS_Attack": "4",
    "FTP_Brute": "5",
    "Ping of Death": "6",
    "Phishing": "7",
    "Fraud VoIP": "8",
    "Open_Proxy": "9",
    "Web_Spam": "10",
    "Email_Spam": "11",
    "Blog_Spam": "12",
    "VPN IP": "13",
    "Port_Scan": "14",
    "Hacking": "15",
    "SQL Injection": "16",
    "Spoofing": "17",
    "Brute_Force": "18",
    "Bad_Web_Bot": "19",
    "Exploited_Host": "20",
    "Web_App_Attack": "21",
    "SSH": "22",
    "IoT_Targeted": "23"
}

session = requests.session()


''' HELPER FUNCTIONS '''


def http_request(method, url_suffix, params=None, headers=HEADERS, threshold=THRESHOLD):
    LOG('running request with url=%s' % (SERVER + url_suffix))
    try:
        analysis = session.request(method, SERVER + url_suffix, headers=headers, params=params, verify=not INSECURE)

        if analysis.status_code not in {200, 204, 429}:
            return_error('Bad connection attempet. Status code: ' + str(analysis.status_code))
        if analysis.status_code == 429:
            if demisto.params().get('disregard_quota'):
                return 'Too many requests (possibly bad API key). Status code: ' + str(analysis.status_code)
            else:
                return_error('Too many requests (possibly bad API key). Status code: ' + str(analysis.status_code))

        return REPORT_SUCCESS if url_suffix == REPORT_CMD else analysis.json()
    except Exception as e:
        LOG(e)
        return_error(e.message)


def analysis_to_entry(info, threshold=THRESHOLD, verbose=VERBOSE):
    if not isinstance(info, list):
        info = [info]

    context_ip_generic, context_ip, human_readable, dbot_scores = [], [], [], []
    for analysis in info:
        ip_ec = {
            "Address": analysis.get("ipAddress"),
            "Geo": {"Country": analysis.get("countryName") or analysis.get("countryCode")}
        }
        abuse_ec = {
            "IP": {
                "Address": analysis.get("ipAddress"),
                "Geo": {"Country": analysis.get("countryName") or analysis.get("countryCode")},
                'AbuseConfidenceScore': analysis.get('abuseConfidenceScore'),
                "TotalReports": analysis.get("totalReports") or analysis.get("numReports") or "0"
            }
        }

        if verbose:
            reports = sum([report_dict.get("categories") for report_dict in analysis.get("reports")], [])  # type: list
            categories = set(reports)
            abuse_ec["IP"]["Reports"] = {CATEGORIES_NAME[c]: reports.count(c) for c in categories}

        human_readable.append(abuse_ec['IP'])

        dbot_score = getDBotScore(analysis, threshold)
        if dbot_score == 3:
            ip_ec["Malicious"] = abuse_ec["IP"]["Malicious"] = {
                'Vendor': "AbuseIPDB",
                'Detections': 'The address was reported as Malicious by AbuseIPDB.',
                'Description': 'The address was reported as Malicious by AbuseIPDB.'

            }
        dbot_scores.append({
            "Score": dbot_score,
            "Vendor": "AbuseIPDB",
            "Indicator": analysis.get("ipAddress"),
            "Type": "ip"
        })
        context_ip.append(abuse_ec)
        context_ip_generic.append(ip_ec)

    return createEntry(context_ip, context_ip_generic, human_readable, dbot_scores, title=ANALYSIS_TITLE)


def blacklist_to_entry(data, saveToContext):
    if not isinstance(data, list):
        data = [data]

    ips = [d.get("ipAddress") for d in data]
    context = {"Blacklist": ips}
    temp = demisto.uniqueFile()
    with open(demisto.investigation()['id'] + '_' + temp, 'wb') as f:
        wr = csv.writer(f, quoting=csv.QUOTE_ALL)
        for ip in ips:
            wr.writerow([ip])
    entry = {
        'HumanReadable': '',
        'Contents': ips,
        'ContentsFormat': formats['json'],
        'Type': entryTypes['file'],
        'File': "Blacklist.csv",
        'FileID': temp,
        'EntryContext': {'AbuseIPDB': createContext(context if saveToContext else None, removeNull=True)}
    }
    return entry


def getDBotScore(analysis, threshold=THRESHOLD):
    total_reports = analysis.get("totalReports") or analysis.get("numReports") or 0
    abuse_score = int(analysis.get("abuseConfidenceScore"))
    dbot_score = 0 if total_reports == 0 else 1 if abuse_score < 20 else 2 if abuse_score < int(threshold) else 3
    return dbot_score


def createEntry(context_ip, context_ip_generic, human_readable, dbot_scores, title):
    entry = {
        'ContentsFormat': formats['json'],
        'Type': entryTypes['note'],
        'Contents': context_ip,
        'ReadableContentsFormat': formats['markdown'],
        'HumanReadable': tableToMarkdown(title, human_readable, removeNull=True),
        'EntryContext': {
            'IP(val.Address && val.Address == obj.Address)': createContext(context_ip_generic, removeNull=True),
            'AbuseIPDB(val.IP.Address && val.IP.Address == obj.IP.Address)': createContext(context_ip, removeNull=True),
            'DBotScore': createContext(dbot_scores, removeNull=True)
        }
    }
    return entry


''' FUNCTIONS '''


def check_ip_command(ip, days=MAX_AGE, verbose=VERBOSE, threshold=THRESHOLD):
    params = {
        "ipAddress": ip,
        "maxAgeInDays": days
    }
    if verbose:
        params['verbose'] = "verbose"
    analysis = http_request("GET", url_suffix=CHECK_CMD, params=params).get("data")
    return analysis_to_entry(analysis, verbose=verbose, threshold=threshold)


def check_block_command(network, limit, days=MAX_AGE, threshold=THRESHOLD):
    params = {
        "network": network,
        "maxAgeInDays": days
    }
    analysis = http_request("GET", url_suffix=CHECK_BLOCK_CMD, params=params).get("data").get("reportedAddress")
    return analysis_to_entry(analysis[:int(limit) if limit.isdigit() else 40], verbose=False, threshold=threshold)


def report_ip_command(ip, categories):
    params = {
        "ip": ip,
        "categories": ",".join([CATEGORIES_ID[c] if c in CATEGORIES_ID else c for c in categories.split()])
    }
    analysis = http_request("POST", url_suffix=REPORT_CMD, params=params)
    return analysis


def get_blacklist_command(limit, days, saveToContext):
    params = {
        'maxAgeInDays': days,
        "limit": limit
    }
    analysis = http_request("GET", url_suffix=BLACKLIST_CMD, params=params)
    return analysis if type(analysis) is str else blacklist_to_entry(analysis.get("data"), saveToContext)


def test_module():
    try:
        check_ip_command(ip=TEST_IP, verbose=False)
    except Exception as e:
        LOG(e)
        return_error(e.message)
    demisto.results('ok')


def get_categories_command():
    categories = {str(key): value for key, value in CATEGORIES_NAME.items()}
    entry = {
        'ContentsFormat': formats['json'],
        'Type': entryTypes['note'],
        'Contents': categories,
        'ReadableContentsFormat': formats['markdown'],
        'HumanReadable': tableToMarkdown("AbuseIPDB report categories", categories, removeNull=True),
        'EntryContext': {'AbuseIPDB.Categories(val && val == obj)': createContext(categories, removeNull=True),
                         }
    }
    return entry


try:
    if demisto.command() == 'test-module':
        # Tests connectivity and credentails on login
        test_module()
    elif demisto.command() == 'ip':
        demisto.results(check_ip_command(**demisto.args()))
    elif demisto.command() == 'abuseipdb-check-cidr-block':
        demisto.results(check_block_command(**demisto.args()))
    elif demisto.command() == 'abuseipdb-report-ip':
        demisto.results(report_ip_command(**demisto.args()))
    elif demisto.command() == 'abuseipdb-get-blacklist':
        demisto.results(get_blacklist_command(**demisto.args()))
    elif demisto.command() == 'abuseipdb-get-categories':
        demisto.results(get_categories_command(**demisto.args()))  # type:ignore

except Exception as e:
    LOG.print_log()
    return_error(e.message)

import requests
import json
import time
import datetime
import os

import urllib3
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

from requests.packages.urllib3.exceptions import InsecureRequestWarning
requests.packages.urllib3.disable_warnings(InsecureRequestWarning)

if not demisto.params()['proxy']:
    del os.environ['HTTP_PROXY']
    del os.environ['HTTPS_PROXY']
    del os.environ['http_proxy']
    del os.environ['https_proxy']

''' GLOBAL VARS '''
URL = demisto.getParam('url') + '/aellaelastic'
USERNAME = demisto.getParam('credentials')['identifier']
PASSWORD = demisto.getParam('credentials')['password']
FETCH_INTERVAL = demisto.getParam('fetch_interval')
VALIDATE_CERT = not demisto.params().get('insecure', True)

''' HELPER FUNCTIONS '''
def make_rest_call(end_point, username, password, action_result,
    headers={}, params=None,
    data=None, method='get'):
    headers.update({'Accept': 'application/json'})
    headers.update({'Content-Type': 'application/json'})

    resp_json = None
    request_func = getattr(requests, method)
    if (not request_func):
        action_result['status']='Unsupported method {}'.format(method)
        return
    try:
        r = request_func(end_point, auth=(username, password),
            data=json.dumps(data) if data else None,
            headers=headers,
            verify=VALIDATE_CERT,params=params)
    except Exception as e:
        action_result['status']='Server REST API exception {}'.format(e)
        return

    if r is not None:
        action_result['r_text']=r.text
        action_result['headers']=r.headers
        action_result['r_status_code']=r.status_code

    try:
        resp_json = r.json()
    except Exception as e:
        action_result['status']='Json parse error {}'.format(
            r.text.replace('{', ' ').replace('}', ' '))
        return

    if (200 <= r.status_code <= 399):
        action_result['status'] = 'Success'
    else:
        action_result['status'] = 'Failed'

    action_result['data'] = resp_json
    return

''' FUNCTIONS '''
def fetch_incidents_command():
    fetch_interval = demisto.getParam('fetch_interval')
    if fetch_interval is None:
        fetch_interval = 15 * 60 # 15 minutes
    else:
        try:
            fetch_interval = int(fetch_interval) * 60
            if fetch_interval < 15 * 60:
                # Min is 15 minutes
                fetch_interval = 15 * 60
        except:
            fetch_interval = 15 * 60

    cur_t = time.time()

    checkTime = cur_t - fetch_interval

    event = demisto.getParam('event_name')
    if event is None:
        event = '*'

    score = demisto.getParam('severity')
    if score:
        try:
            score = int(score)
            if score < 0 or score > 100:
                score = 50
        except:
            score = 50
    else:
        # Default score
        score = 50

    index_str = 'aella-ser*'

    query_str = 'event_name:{}  AND severity:>{}'.format(event, score)

    ts_str = str(long(checkTime * 1000))

    query_json = { 'query':
        { 'bool':
            { 'must':
                [ { 'query_string':
                    {
                      'query': query_str,
                      'analyze_wildcard': True
                    }
                  },
                  { 'range':
                     { 'timestamp':
                         { 'gt': ts_str }
                     }
                  }
                ]
            }
        }
    }
    end_point = URL + '/{0}/{1}/_search'.format(index_str, 'amsg')

    action_result = {}
    make_rest_call(end_point,
        USERNAME, PASSWORD, action_result, data=query_json
    )

    if action_result['status'] == 'Success':
        demisto.info('Poll incidents ok')
        data = action_result.get('data')
        if not isinstance(data, dict):
            demisto.error('Data returned in wrong format {}'.format(data))
            demisto.incidents([])
            return
        hits = data.get('hits', {}).get('hits', [])
        incidents = []

        try:
            cached_event = demisto.getLastRun().get("cached_event", {})
        except:
            cached_event = {}

        new_cached_event = {}

        for hit in hits:
            source = hit.get('_source', None)
            if not source:
                continue
            event_name = source.get('event_name', None)
            try:
                event_severity = int(source.get('severity', None))
                if event_severity > 75:
                    severity = 3
                elif event_severity > 50:
                    severity = 2
                else:
                    severity = 1
            except:
                severity = 0

            if not event_name:
                continue
            eid = hit['_id']

            new_cached_event[eid] = True
            if cached_event.get(eid, False):
                continue

            sdi = '{}_{}'.format(event_name, eid)
            incident = {
                'name' : sdi,
                'severity' : severity,
                'rawJSON':json.dumps({  'name':sdi,
                                        'label':'Starlight event',
                                        'aella_eid': eid,
                                        'aella_event':event_name,
                                        'event_severity': event_severity
                                    })
            }
            incidents.append(incident)
        demisto.info('Incidents is {}'.format(incidents))
        demisto.setLastRun({'cached_event': new_cached_event})
        demisto.incidents(incidents)

    else:
        demisto.info('Poll incidents failed {}'.format(action_result))
        demisto.incidents([])

def aella_get_event_command():
    demisto.info('Aella started get-event with {}'.format(demisto.args()['event_id']))
    event_id = demisto.args()['event_id']
    query_json = { 'query': { 'match': { '_id': event_id } } }
    end_point = URL + '/{0}/{1}/_search'.format('aella-ser*', 'amsg')

    action_result = {}
    make_rest_call(end_point,
        USERNAME, PASSWORD, action_result, data=query_json
    )
    if action_result['status'] == 'Success':
        demisto.info('Run Query is successful')
        response = action_result.get('data')
        timed_out = response.get('timed_out', False)
        hits = response.get('hits', {}).get('hits', [])
        source = {}
        dbot_scores = []
        if len(hits) == 0:
            demisto.info('Get event got empty result')
        for item in hits:
            index = item.get('_index', '')
            source = item.get('_source', {})
            if index:
                source['_index'] = index
                source['timed_out'] = timed_out
                demisto.debug('This is my run_query result aellaEvent {}'.format(source))

                # Check url reputation
                url_str = source.get('url', '')
                if url_str:
                    url_reputation = source.get('url_reputation', '')
                    if url_reputation and url_reputation != 'Good':
                        dbot_score = {
                            'Vendor' : 'Aella Data',
                            'Indicator' : url_str,
                            'Type' : 'url',
                            'Score' : 3,
                            'Malicious' : {
                                'Vendor' : 'Aella Data',
                                'Detections' : 'URL reputation {0}'.format(url_reputation),
                                'URL' : url_str
                            }
                        }
                    else:
                        dbot_score = {
                            'Vendor' : 'Aella Data',
                            'Indicator' : url_str,
                            'Type' : 'url',
                            'Malicious' : None
                        }
                        if url_reputation is None:
                            # Unknonw
                            dbot_score['Score'] = 0
                        else:
                            # Good
                            dbot_score['Score'] = 1
                    dbot_scores.append(dbot_score)

                # Check src ip reputation
                srcip_str = source.get('srcip', '')
                if srcip_str:
                    srcip_reputation = source.get('srcip_reputation', '')
                    if srcip_reputation and srcip_reputation != 'Good':
                        dbot_score = {
                            'Vendor' : 'Aella Data',
                            'Indicator' : srcip_str,
                            'Type' : 'ip',
                            'Score' : 3,
                            'Malicious' : {
                                'Vendor' : 'Aella Data',
                                'Detections' : 'Source IP reputation {0}'.format(srcip_reputation),
                                'IP' : srcip_str
                            }
                        }
                    else:
                        dbot_score = {
                            'Vendor' : 'Aella Data',
                            'Indicator' : srcip_str,
                            'Type' : 'ip',
                            'Malicious' : None
                        }
                        if srcip_reputation is None:
                            # Unknonw
                            dbot_score['Score'] = 0
                        else:
                            # Good
                            dbot_score['Score'] = 1
                    dbot_scores.append(dbot_score)

                # Check dst ip reputation
                dstip_str = source.get('dstip', '')
                if dstip_str:
                    dstip_reputation = source.get('dstip_reputation', '')
                    if dstip_reputation and dstip_reputation != 'Good':
                        dbot_score = {
                            'Vendor' : 'Aella Data',
                            'Indicator' : dstip_str,
                            'Type' : 'ip',
                            'Score' : 3,
                            'Malicious' : {
                                'Vendor' : 'Aella Data',
                                'Detections' : 'Destination IP reputation {0}'.format(dstip_reputation),
                                'IP' : dstip_str
                            }
                        }
                    else:
                        dbot_score = {
                            'Vendor' : 'Aella Data',
                            'Indicator' : dstip_str,
                            'Type' : 'ip',
                            'Malicious' : None
                        }
                        if dstip_reputation is None:
                            # Unknonw
                            dbot_score['Score'] = 0
                        else:
                            # Good
                            dbot_score['Score'] = 1
                    dbot_scores.append(dbot_score)

            break
        demisto.results({
            'Type': entryTypes['note'],
            'ContentsFormat': formats['json'],
            'Contents': source,
            'HumanReadable': tableToMarkdown('Aella Star Light Event <{0}>'.format(event_id), source),
            'EntryContext': {
                'Aella.Event(val._id==obj._id)': source,
                'DBotScore' : createContext(dbot_scores, removeNull=True),
            }
        })
    else:
        demisto.info('Get event failed {}'.format(action_result))
        demisto.results(return_error('Failed to get event'))

''' EXECUTION CODE '''
demisto.info('Command is {}'.format(demisto.command()))

if demisto.command() == 'test-module':
    # This is the call made when pressing the integration test button.
    action_result = {}
    make_rest_call(URL + '/_cluster/health',
        USERNAME, PASSWORD, action_result
        )

    if action_result['status'] == 'Success':
        demisto.results('ok')
    else:
        demisto.results('failed')

if demisto.command() == 'fetch-incidents':
    fetch_incidents_command()

if demisto.command() == 'aella-get-event':
    aella_get_event_command()

import xml.etree.ElementTree as ET  # type: ignore
import requests

# Disable insecure warnings
requests.packages.urllib3.disable_warnings()


"""GLOBAL VARIABLES/CONSTANTS"""
THRESHOLD = int(demisto.params().get('threshold'))
USE_SSL = not demisto.params().get('insecure', False)


"""COMMAND FUNCTIONS"""


def alexa_domain_command():
    domain = demisto.args().get('domain')
    resp = requests.request('GET', 'https://data.alexa.com/data?cli=10&dat=s&url={}'.format(domain), verify=USE_SSL)
    root = ET.fromstring(str(resp.content))
    try:
        rank = root.find("SD[0]/POPULARITY").attrib['TEXT']  # type: ignore
        if int(rank) > THRESHOLD:
            dbot_score = 2
            dbot_score_text = 'suspicious'
        else:
            dbot_score = 0
            dbot_score_text = 'unknown'
    except AttributeError:
        rank = 'Unknown'
        dbot_score = 2
        dbot_score_text = 'suspicious'
    dom_ec = {'Name': domain}
    dbot_ec = {
        'Score': dbot_score,
        'Vendor': 'Alexa Rank Indicator',
        'Domain': domain,
        'Type': 'domain'
    }
    ec = {
        'Domain(val.Name && val.Name == obj.Name)': dom_ec,
        'DBotScore': dbot_ec,
        'Alexa.Domain(val.Name && val.Name == obj.Domain.Name)': {
            'Name': domain,
            'Rank': rank
        }
    }
    hr_string = ('The Alexa rank of {} is {} and has been marked as {}'
                 ' while the threshold is {}'.format(domain, rank, dbot_score_text, THRESHOLD))
    demisto.results({
        'Type': entryTypes['note'],
        'ContentsFormat': formats['markdown'],
        'Contents': xml2json(resp.content),
        'HumanReadable': hr_string,
        'EntryContext': ec
    })


