    }
    // If we have a body, it should have application/json content type.
    if (res.Body &&
    (!res.Headers['Content-Type'] || !res.Headers['Content-Type'][0] || res.Headers['Content-Type'][0].indexOf('application/json') === -1) || res.Body.indexOf('Google Tag Manager') != -1) {
        log('Response body: ' + res.Body);
        throw 'Check your URL (excepting base URL) - got invalid content type, expected application/json.';
    }
    return res.Body ? JSON.parse(res.Body) : 'empty';
}

