        for raw_event in correlated_events:
            base_event_ids = raw_event.get('baseEventIds')
            if base_event_ids:
                if isinstance(base_event_ids, list):
                    related_ids.update(base_event_ids)
                else:
                    related_ids.add(base_event_ids)

    return list(related_ids)


