    findingIdsForArchive = []
    id_list = finding_ids.replace(" ", "")
    findingsids = id_list.split(",")
    for id in findingsids:
        findingIdsForArchive.append({
            'Value': id,
            'Comparison': 'EQUALS'
        })
    return findingIdsForArchive

