    try:
        client = aws_session()
        incidents = []

        last_run = demisto.getLastRun().get('lastRun', None)
        if last_run is None:
            time = datetime.datetime.utcnow() - datetime.timedelta(days=15)
            last_run = time.isoformat("T") + "Z"

        d = datetime.datetime.utcnow() # <-- get time in UTC

        filters = {
            "CreatedAt": [{
                "Start": str(last_run),
                "End": str(d.isoformat("T") + "Z")
            }],
        "SeverityNormalized": [{
