    if (!Array.isArray(users)) {
        users = [users];
    }

    if (verbose=='true') {
        for (var i=0;i<users.length;i++) {
            md += '#### ' + users[i].login + '\n';
            var head='|';
            var line='|';
            var data='|';
            for (var key in users[i]) {
                head += key + '|';
                line += '-|';
                data += users[i][key] + '|';
            }
            md += head + '\n' + line + '\n' + data + '\n';
        }

    } else {
        var head = '|';
        var line = '|';
        for (var key in userTableDict) {
            head += userTableDict[key] + '|';
            line += '-|';
        }
        md += head + '\n' + line + '\n';

        for (var i=0;i<users.length;i++) {
            md += '|';
            for (var key in userTableDict) {
                md += users[i][key] + '|';
            }
            md += '\n';
        }
    }
    return md;

};


