def add_domain(domain, newscan):
    if newscan == 'true':
        newscan = 1
    else:
        newscan = 0

    params = {
        'apikey': API_KEY,
        'domain': domain,
        'newscan': newscan
    }
    call = requests.get(ENDPOINTURL + '/iriskaddcompany', headers=HEADERS, verify=USE_SSL, params=params)

    if call.status_code == requests.codes.ok:
        result_dictionary = {
            'result': call.json()['result'],
