    params = {
        'apikey': API_KEY,
        'domain': domain
    }
    call = requests.get(ENDPOINTURL + '/iRiskRescanCompany', headers=HEADERS, verify=USE_SSL, params=params)
    if call.status_code == requests.codes.ok:
        md = tableToMarkdown('Rescan domain Results', call.json())
