    # running the API command
    reports = http_request(url_suffix='/processed_reports', params=params)

    # loading last_run
    last_run = json.loads(demisto.getLastRun().get('value', '{}'))
    already_fetched = last_run.get('already_fetched', [])

    # parsing outputs
