        if(!isNaN(args[k])){
            args[k] = args[k].toString();
        }
        var parts = argToList(args[k]);
        for (var i=0; i<parts.length; i++) {
            // check if the argument is a number
            if(!isNaN(parts[i])){
                parts[i] = parts[i].toString();
            }
            parts[i] = parts[i].trim();
        }
        a[k] = f ? f(args[k]) : parts.length > 1 ? parts : parts[0];
    }
}

