function detonateFile(entryId, delay, timeout) {
    var environmentId;
    if (args.environmentID) {
        environmentId = args.environmentID;
    } else {
        var environments = getEnvironments().backend.global_environment;
        for (var i=0; i<environments.length; i++) {
            if (environments[i]['ID'] === 100) {
                environmentId = 100;
                break;
             } else if (environments[i]['architecture'] === 'WINDOWS') {
                environmentId = environments[i]['ID'];
                break;
                } else {
                    throw 'Please enter valid environment ID';
            }
        }
    }
    var file = submitFile(entryId, environmentId.toString());
    var hash = file.sha256;

    delayTime = parseInt(delay);
    timeOut = parseInt(timeout);
    var waitTime = delayTime;

    wait(delayTime);
    while (waitTime<timeOut) {
        var res = scan(hash);
        if (res.length > 0) {
            return scanToEntry(res);
        } else {
            waitTime = waitTime + delayTime;
            wait(delayTime);
        }
    }
    throw ('Timeout due to no answer after ' + timeOut + ' seconds.');

}

//Dbot score calculation for a response without 'threat_level' field
function calculateDbotScore(unknownCounter, maliciousCounter,minMaliciousScanners, numOfScanners){
    var dbotScore = 0;

    if (maliciousCounter >= minMaliciousScanners)
        dbotScore = 3;
    else if (maliciousCounter >= 1)
        dbotScore = 2;
    else if (unknownCounter == numOfScanners)
        dbotScore = 0;
    else if (maliciousCounter == 0) // some scanners found it clean and no scanner found it malicious
        dbotScore = 1;

    return dbotScore;
}


