            md += cveToMd(o[i]) + '\n';
            ec.push(cveToContext(o[i]));
        }
        if (ec.length > 0) {
            context[outputPaths.cve] = ec;
        }
    } else {
        md += 'No result found.';
    }
    return {Type: entryTypes.note, Contents: res.body, ContentsFormat: formats.json, HumanReadable: md, EntryContext: context};
}


