def get_query_args(demisto_args):
    str_args = ('model', 'view')
    list_args = ('fields', 'pivots', 'sorts')
    args_dict = {k: argToList(demisto_args[k]) for k in list_args if k in demisto_args}  # Parse list-type arguments
