@logger
def cases_to_entry(esm, title, cases):
    if not cases:
        return 'No cases were found'

    headers = ['ID', 'Summary', 'Status', 'Severity', 'OpenTime']
    fixed_cases = []
    context_cases = []

    for case in cases:
        fixed_case = {
            'ID': case['id']['value'],
