def number_to_ip(n):
    if isinstance(n,str):
        return n
    try:
        return socket.inet_ntoa(struct.pack('!L', long(n)))
    except:
        return n

def ip_to_number(i):
    try:
        return struct.unpack('!L', socket.inet_aton(i))[0]
    except:
        return i

