@logger
def panorama_list_pcaps_command():
    """
    Get list of pcap files
    """
    params = {
        'type': 'export',
        'key': API_KEY,
        'category': demisto.args()['pcapType']
    }

    if 'password' in demisto.args():
        params['dlp-password'] = demisto.args()['password']
