    // run the test again for the domain since it doesn't have the http:// part
    if (url === report.url){
        delete report.domain;
    } else if (url === report.domain){
        delete report.url;

    }
    md = tableToMarkdown('Phish.AI Scan report ' + url + '. Scan ID: ' + scan_id, report);
