var calcVerdict = function (dbotScore) {
    switch (dbotScore){
        case 0:
            return 'Unknown';
        case 2:
            return 'Suspicious';
        case 3:
            return 'Bad';
    }
}

var calcScore = function (severityLevel) {
    switch (severityLevel){
        case 'None':
            return 0;
        case 'Minor':
            return 2;
        case 'Moderate':
            return 2;
        case 'Major':
            return 3;
        default:
            return -1;
    }
}


