    if (data.timestamp < now-(3600*1000*listUpdateIntervalHours)) {
        return true;
    }
    return false;
}

var removeLastSlash=function(pUrl) {
    var url=pUrl;
    if (url) {
        if (url[url.length - 1] == '/') {
            url = url.substr(0,url.length - 1);
        }
    }
    return url;
}
