        {'from': 'riskScore', 'to': 'RiskScore'},
        {'from': 'assessedForVulnerabilities', 'to': 'Assessed'},
        {'from': 'LastScanDate', 'to': 'LastScanDate'},
        {'from': 'LastScanId', 'to': 'LastScanId'}
