def get_search_filters(text_filters):
    filters = []
    for text in text_filters:
        components = text.split(' ')
        field = components[0]
        operator = components[1]
        value = components[2].split(',')
        # Convert numbers to floats if values are numbers
        for i, v in enumerate(value):
            curr_val = None
            try:
                curr_val = float(v)
            except Exception:
                curr_val = v
            value[i] = curr_val

        flt = {
            'field': field,
            'operator': operator,
        }
        if len(value) > 1:
            if operator in RANGE_OPERATORS:
                flt['lower'] = value[0]
                flt['upper'] = value[1]
            else:
                flt['values'] = value
        else:
            flt['value'] = value[0]
        filters.append(flt)
    return filters


