        'Status': a.get('review', {}).get('status'),
        'Assignee': a.get('review', {}).get('assignee'),
        'Rule': a.get('rule', {}).get('name')
    } for a in response['data'].get('results', [])]

    if len(mapped_alerts) == 0:
        demisto.results('No results found')
