function extractObjectFromXML(xml, path) {
    var searchRes = dq(xml, path);
    if (searchRes === "" || searchRes === null){
        return [];
    }
    if (searchRes.indexOf("<?xml") > -1) {
        var index = searchRes.indexOf(">");
        if (index !== -1) {
            searchRes = searchRes.substr(index + 1);
