function parseResponse(resp, isXml) {
    if (resp.StatusCode === 200) {
        try {
            var body = resp.Body;
            if(isXml){
                body = x2j(body);
            }
            var res = JSON.parse(body);

            return res;
        } catch (e) {
            return body;
        }
    } else {
        err = resp.Status;
        if (resp.Body) {
            err += '\n' + resp.Body;
        }
        throw err;
    }
}

