function makeUpperCase (o) {
    for (var key in o ) {
        if(o.hasOwnProperty(key)) {
            var newKey = key.charAt(0).toUpperCase() + key.slice(1);
            o[newKey] = o[key];
            delete o[key];
        }
    }
    return o;
}

