function calculateDBotScore(res, args, commandData) {
    var dbotScore = 0;
    if (res.response_code == 1){
         if ('votes' in res){
            switch (res.votes) {
                case -1: //malicious
                    dbotScore = 3
                    break;
                case 0: //suspicious
                    dbotScore = 2;
                    break;
                case 1: //clean
                    dbotScore = 1;
                    break;
            }
        }
    }
    return dbotScore;
}

