        waitForRateLimit = parseInt(waitForRateLimit);
    }
    if (!waitForRateLimit) {
        waitForRateLimit = 60;
    }
    if (retries) {
        retries = parseInt(retries);
    }
    if (!retries) {
        retries = 0;
    }
    var res = reqCall();
    var tries = 0;
    while (res.statusCode === 204 && !res.body && tries < retries && waitForRateLimit > 0) {
        wait(waitForRateLimit);
        tries++;
