function calcRecentDownloads(checks) {
    var badDownloads = 0;
    var now = Date.now();
    for (var c=0; c<checks.length; c++) {
        if (checks[c]) {
            for (var ci=0; ci<checks[c].length; ci++) {
                if (checks[c][ci].date) {
                    var d = new Date(checks[c][ci].date.replace(' ', 'T'));
