def get_jwt(apiKey, apiSecret):
    """
    Encode the JWT token given the api ket and secret
    """
    tt = datetime.datetime.now()
    expire_time = int(tt.strftime('%s')) + 5000
    payload  = {
        'iss': apiKey,
        'exp': expire_time
    }
    encoded = jwt.encode(payload, apiSecret, algorithm='HS256')
    return encoded


